{
  "name": "reel-editing-skills",
  "owner": { "name": "Charlie Hills", "url": "https://github.com/charlie947" },
  "metadata": {
    "description": "41 skills that turn a to-camera recording into a polished motion video with Claude Code: product demos, explainers, founder takes, news reactions, clips from your calls and webinars, your brand, every platform size, and 20 one-command effects on your own clip.",
    "version": "1.0.0"
  },
  "plugins": [
    {
      "name": "reel-editing-skills",
      "source": "./",
      "description": "Edit to-camera motion videos for any business with Claude Code. One build, every platform. 21 editing skills plus 20 one-command effects.",
      "version": "1.0.0",
      "author": { "name": "Charlie Hills" },
      "license": "MIT",
      "skills": "./skills"
    }
  ]
}

// Your video. Claude edits this file, never index.html.
// Times are seconds in the CUT recording (after silences are removed).
window.VIDEO = {
  fps: 30,
  duration: 6,          // length of cut-audio.wav
  faceFrames: 1,        // how many JPGs are in face/ (the demo ships one still)
  capWords: 4,          // words per caption group
  hook: ['Claude edits my videos now', 'Here are the 3 moves I use:'],  // 2 lines, no full stop
  hookEnd: 2.2,         // cut from the hook to the edit at about 2.2s

  // Keep the caption band clear on every beat: y 930-1040 on Instagram, y 590-700 on LinkedIn.
  // Size objects from PANEL (PANEL.split, PANEL.full) so the same beat renders both cuts.
  beats: [
    // 1. Your face from frame 0, the hook does the talking
    { start: 0, end: 2.2, layout: 'face' },

    // 2. Split: one big object on top, your face below. It lands on its word.
    { start: 2.2, end: 4.2, layout: 'split',
      html: `<div class="hero" style="position:absolute;left:140px;top:${PANEL.split * 0.14}px;width:800px;height:${PANEL.split * 0.68}px;border-radius:44px;background:#fff;box-shadow:0 40px 80px -40px rgba(0,0,0,.35);display:flex;align-items:center;justify-content:center;font-size:150px;font-weight:800;color:#0071e3">3x</div>`,
      draw(lt, el) {
        const p = spring(prog(lt, 0, 0.5));
        el.firstChild.style.transform = `perspective(1400px) translateZ(${(1 - p) * -900}px) rotateX(${(1 - p) * 18}deg)`;
        el.firstChild.style.opacity = prog(lt, 0, 0.15);
      } },

    // 3. Full graphic, face hidden
    { start: 4.2, end: 6, layout: 'full',
      html: `<div style="position:absolute;left:0;right:0;top:${PANEL.full * 0.2}px;text-align:center;font-size:120px;font-weight:800;letter-spacing:-0.03em">Your payoff</div>`,
      draw(lt, el) { el.firstChild.style.opacity = easeOut(prog(lt, 0, 0.3)); } },
  ],
};

// Effect 07 Cube Spin: the shot is the front of a cube. It pulls back a touch and turns a quarter, and the next effect is on the side face.
(() => {
  const W = Z.w, H = Z.h;
  // absolute seconds (the beat is ~1.2s): holds 0-0.4, one quarter turn to 0.08s before the end, lands flat
  const sp = (t, d) => eio(P(t, .4, Math.max(.4, d - .48)));
  FX[7] = {
    name: NAMES[6], row: 6, bg: 'blue', Send: 1,
    html() { return `<style>.fx7p{perspective:${(2.6 * W).toFixed(0)}px;perspective-origin:50% 50%}
        .fx7c{transform-style:preserve-3d;transform-origin:50% 50%}
        .fx7f{position:absolute;left:0;top:0;width:${W}px;height:${H}px;overflow:hidden;backface-visibility:hidden;-webkit-backface-visibility:hidden;transform-origin:50% 50%}
</style>
      <div class="Z fx7p"><div class="Z fx7c">
        <div class="fx7f fx7a" style="transform:translateZ(${W / 2}px)">${himView(PT(7), 'me')}</div>
        <div class="fx7f fx7b" style="transform:rotateY(90deg) translateZ(${W / 2}px)">${SLOT}</div>
      </div></div>`; },
    camera(t, d) { const s = sp(t, d); return s > 0 && s < 1 ? { a: ZC, f: ZC, S: 1 - .3 * Math.sin(Math.PI * s) } : null; },
    seek(cam, t, d) { const s = sp(t, d), th = 90 * s;
      one(cam, '.fx7c').style.transform = `translateZ(${-W / 2}px) rotateY(${(-th).toFixed(3)}deg)`;
      const sh = x => x > .001 ? `brightness(${(1 - .35 * x).toFixed(3)})` : 'none';   // the face turning away darkens (a filter on the face, nothing laid over him)
      one(cam, '.fx7a').style.filter = sh(Math.sin(Math.PI / 2 * s)); one(cam, '.fx7b').style.filter = sh(Math.cos(Math.PI / 2 * s));
      if (FACEF) { one(cam, '.fx7a').style.opacity = (1 - P(s, .3, .2)).toFixed(3); one(cam, '.fx7b').style.opacity = P(s, .5, .2).toFixed(3); } },   // never two faces on the cube at once
    win() { return { c: ZC, w: Z.w, h: Z.h, rr: 0 }; },
    winIn: (t, d) => t > .3 ? 1 : 0,
  };
})();

// Effect 06 Infinite Zoom: a framed copy of the empty stage appears beside him, with a frame inside it. We zoom through both into the next effect.
// No copy of the face in the frames (two faces at once reads badly). The next effect fades in late, once the inner frame is big.
(() => {
  const f = V === 'L' ? .26 : .3, w1 = Z.w * f, p = V === 'L' ? [Z.w - w1 - 14, Z.h * .56] : V === 'A' ? [Z.w - w1 - 24, 60] : [1080 - w1 - 40, 380];
  const M = x => [p[0] + f * x[0], p[1] + f * x[1]], FP = [p[0] / (1 - f), p[1] / (1 - f)];   // FP: the fixed point of the copy map, the camera scales about it
  const rect = k => { const s = Math.pow(f, k), o = k === 1 ? p : M(p); return { x: o[0], y: o[1], w: Z.w * s, h: Z.h * s, s }; };
  const R1 = rect(1), R2 = rect(2), BW = 5;
  // absolute seconds (the beat is ~1.2s): the copy appears 0.04-0.28, holds, then one continuous zoom from 0.5s to the end
  const zz = (t, d) => eio(P(t, .5, d - .5));
  FX[6] = {
    name: NAMES[5], row: 5, bg: 'floor', Send: 1 / (f * f),
    html() { return `<style>.fx6c{position:absolute;overflow:hidden;background-color:#f3f5f8;background-image:linear-gradient(rgba(29,29,31,.06) 2px,transparent 2px),linear-gradient(90deg,rgba(29,29,31,.06) 2px,transparent 2px);background-size:${(90 * f).toFixed(1)}px ${(90 * f).toFixed(1)}px}
        .f[data-s=blue] .fx6c{background-color:#0b3a7a;background-image:linear-gradient(rgba(255,255,255,.08) 2px,transparent 2px),linear-gradient(90deg,rgba(255,255,255,.08) 2px,transparent 2px)}
        .fx6b{position:absolute;outline:${BW}px solid #fff;box-shadow:0 18px 40px -10px rgba(0,19,47,.38)}
        .fx6b2{position:absolute;outline:${(BW * f).toFixed(2)}px solid #fff}</style>
      ${himView(PT(6), 'me')}
      <div class="fx6k"><div class="fx6b" style="left:${R1.x}px;top:${R1.y}px;width:${R1.w}px;height:${R1.h}px"></div>
        <div class="fx6c" style="left:${R1.x}px;top:${R1.y}px;width:${R1.w}px;height:${R1.h}px"></div>
        <div class="fx6b2" style="left:${R2.x}px;top:${R2.y}px;width:${R2.w}px;height:${R2.h}px"></div></div>${SLOT}`; },
    camera(t, d) { const z = zz(t, d); return z > 0 ? { a: FP, f: FP, S: Math.pow(this.Send, z) } : null; },
    seek(cam, t, d) { const a = ez(P(t, .04, .24)), k = one(cam, '.fx6k'), s = mix(.9, 1, a), c = [R1.x + R1.w / 2, R1.y + R1.h / 2];
      k.style.transformOrigin = `${c[0]}px ${c[1]}px`; k.style.transform = zz(t, d) > 0 ? 'none' : `scale(${s.toFixed(4)})`; k.style.opacity = a.toFixed(3); },
    win() { return { c: [R2.x + R2.w / 2, R2.y + R2.h / 2], w: R2.w, h: R2.h, rr: 0 }; },
    winIn: (t, d) => ez(P(t, .5 + .45 * (d - .5), .25 * (d - .5))),   // late: only once the zoom has made the inner frame big
  };
})();

// Effect 05 Clone Room: a corridor of copies of him steps out behind him, into his own room. The room and the bottom of the frame stay live footage throughout.
(() => {
  // a corridor of clones behind him, receding upward and alternating sides; the farthest first so nearer ones stand in front
  const PW = 1080 * BS, OFF = [-.08, .08, -.22, .22, -.36, .36], SC = [.54, .54, .66, .66, .82, .82], LIFT = [450, 450, 330, 330, 170, 170], CT = [PT(1), PT(3), PT(8), PT(9), PT(6), PT(4)];
  const FADE = 'mask-image:linear-gradient(#000 58%,transparent 80%);-webkit-mask-image:linear-gradient(#000 58%,transparent 80%)';   // clones melt into the room below the chest (room shows through, never white)
  // absolute seconds (the beat is ~1.1s): clones step out 0.1-0.42, hold, step back in over the last 0.44s
  const TM = d => { const dv = Math.max(.62, d - .44); return { dv, dl: d - .1 - dv }; };   // the return ends 0.1s before the cut, then the next shot fades in over him
  FX[5] = {
    name: NAMES[4], row: 4, bg: 'blue', Send: 1,
    html() { const cl = OFF.map((o, i) => `<div class="fx5c" data-i="${i}">${cut(CT[i], 0, 0, BS * SC[i], 'deco', FADE)}</div>`).join('');
      return `<style>.fx5c{position:absolute;left:0;top:0;width:0;height:0}</style>
        ${himView(PT(5), 'me')}<div class="Z fx5w">${cl}${cut(PT(5), Z.w / 2, BEYE, BS, 'me')}</div>${SLOT}`; },   // room plate, clones, then his own cut-out on top
    camera: () => null,   // no pull-back: the room plate must fill the card the whole time
    seek(cam, t, d) { const { dv, dl } = TM(d), step = eio(P(t, .1, .32)) * (1 - eio(P(t, dv, dl)));
            own(cam, '.fx5c').forEach(c => { const i = +c.dataset.i, x = ZC[0] + OFF[i] * PW * step, lift = LIFT[i] * BS / .769;
        c.style.transform = `translate(${x.toFixed(1)}px,${(BEYE - lift).toFixed(1)}px)`; c.style.opacity = (P(t, .06, .14) * (1 - P(t, dv + .5 * dl, .4 * dl))).toFixed(3); }); },
    win(t, d) { return { c: ZC, w: Z.w, h: Z.h, rr: 0 }; },
    winIn: (t, d) => P(t, d - .1, .09),
  };
})();

// Effect 03
// ---------------- 3 Magnifying Lens: a glass disc glides in over his chest and magnifies what is under it (1.4x, never his face). Then it opens out
// gently into the next effect. A loupe on the eyes reads as a second head, so the glass stays on the chest.
const LZ = V === 'L' ? { r: .33 * Z.w, c: [Z.w - 36 - .33 * Z.w, .8 * Z.h] } : V === 'A' ? { r: 175, c: [Z.w - 60 - 175, .74 * Z.h] } : { r: 230, c: [740, 1330] };
const LMAG = 1.4;   // a gentle loupe: his chest under the glass at 1.4x, never his face
const LEYE = [Z.w / 2 + 22 * BS, BEYE + 300 * BS];   // the copy scales about his chin: its (hidden) face stays over his real face, and the glass shows only his chest at 1.4x
const LIN = .88;
const lensAt = (t, K) => { const u = ez(P(t, .04, .46)), p0 = [Z.w + LZ.r + 60, Z.h * .95], m = [Z.w + 20, LZ.c[1] + LZ.r]; return [(1 - u) * (1 - u) * p0[0] + 2 * (1 - u) * u * m[0] + u * u * LZ.c[0], (1 - u) * (1 - u) * p0[1] + 2 * (1 - u) * u * m[1] + u * u * LZ.c[1]]; };
const lensDv = K => Math.max(.85, 2 * K - .5);   // absolute: glide in by 0.5s, hold, dive over the last 0.5s
const lensZ = (t, K) => ez(P(t, lensDv(K), 2 * K - lensDv(K)));
const lensHim = cls => plate(PT(3), Z.w / 2, BEYE, BS, cls);
const LENS = {
  name: 'Magnifying Lens', row: 2, bg: 'blue', Send: .35 * Z.w / (LZ.r * LIN),   // half the old push (1.2x in V1, was 2.4x): the lens opens out gently instead of diving hard at his face
  // window radius: the lens, then it opens out to cover the zone by the hand-off
  wr(t, d) { const K = d / 2, dv = lensDv(K), dl = 2 * K - dv; return mix(LZ.r * LIN, 1.02 * ZD / this.Send, ez(P(t, dv + .05 * dl, .8 * dl))); },
  html() { return `<div class="Z body">${lensHim('me')}</div><div class="Z lensIn"><div class="Z mag" data-noface="1">${lensHim('me')}</div>${SLOT}</div><div class="lensG"></div><div class="lensR"></div>`; },
  camera(t, d) { const z = lensZ(t, d / 2); return z > 0 ? { a: LZ.c, f: [mix(LZ.c[0], ZC[0], z), mix(LZ.c[1], ZC[1], z)], S: Math.pow(this.Send, z) } : null; },
  seek(cam, t, d) { const K = d / 2, z = lensZ(t, K), L = lensAt(t, K), r = LZ.r, band = 1 - P(t, lensDv(K), .15);
    const li = one(cam, '.lensIn'); li.style.clipPath = `circle(${Math.max(r, this.wr(t, d) + 2).toFixed(1)}px at ${L[0].toFixed(1)}px ${L[1].toFixed(1)}px)`;
    const mg = one(cam, '.mag'); mg.style.transformOrigin = '0 0'; mg.style.transform = `translate(${LEYE[0].toFixed(1)}px,${LEYE[1].toFixed(1)}px) scale(${LMAG}) translate(${(-LEYE[0]).toFixed(1)}px,${(-LEYE[1]).toFixed(1)}px)`; mg.style.opacity = (1 - P(t, lensDv(K) - .04, .06)).toFixed(3);   // gone before the circle opens out
    const vis = L[0] - r < Z.w;
    ['.lensG', '.lensR'].forEach(s => Object.assign(one(cam, s).style, { display: vis ? 'block' : 'none', left: (L[0] - r).toFixed(1) + 'px', top: (L[1] - r).toFixed(1) + 'px', width: 2 * r + 'px', height: 2 * r + 'px' }));
    li.style.display = vis ? 'block' : 'none';
    one(cam, '.lensG').style.opacity = (1 - P(t, lensDv(K), .15)).toFixed(3); one(cam, '.lensR').style.opacity = band.toFixed(3); },
  win(t, d) { return { c: lensAt(t, d / 2), r: this.wr(t, d) }; },
  winIn: (t, d) => { const dv = lensDv(d / 2), dl = d - dv; return P(t, dv + .3 * dl, .25 * dl); },   // the next effect fades in late, once the circle is wide, so no small second him is held in the glass
};

FX[3] = LENS;

// One effect on your clip. The timeline: your clip as it is until --at, the effect for --len seconds, then your clip again
// (the effect dives into it, so the hand-off is seamless). Head Pop Out is an ending: it holds to the end of the clip.
// seek is a pure function of T (no state carried between calls), so a check, a still and the render always agree.
const N = SETUP.n, AT = SETUP.at || 0, D = SETUP.D;
if (!FX[N]) throw new Error('no effect ' + N);
const EFF = FX[N];
// your clip at its talking-head framing, live, no window of its own
const PLAIN = { name: 'clip', row: -1, bg: EFF.bg, Send: 1, html() { return `${himView(PT(N), 'me')}${SLOT}`; }, camera: () => null, seek() {}, win: () => ({ c: ZC, w: Z.w, h: Z.h, rr: 0 }), winIn: () => 0 };
// these effects open on their own layout (measured: a jump of 15+ grey levels in the first frame), so they dissolve in from
// your plain shot over XF seconds. The rest open on your plain shot already and need nothing.
const XF = SETUP.xf ?? ([2, 9, 11, 12, 13, 14, 16, 19].includes(N) ? .3 : 0);
const END = N === 20 ? D : Math.min(D, AT + SETUP.len);
const SEG = [];
if (AT > 0) SEG.push([PLAIN, 0, AT, null]);
SEG.push([EFF, AT, END, END < D ? PLAIN : null]);
if (END < D) SEG.push([PLAIN, END, D, null]);
let UID = 0;
function build(el) {
  el.className = 'f'; el.dataset.v = V; el.dataset.s = ST === 'blue' ? 'blue' : 'white'; el.dataset.stage = ST; const u = 'z' + (UID++);
  el.style.setProperty('--zw', Z.w + 'px'); el.style.setProperty('--zh', Z.h + 'px');
  el.innerHTML = `<div class="L stage"><div class="L sb">${STAGE.blue}</div><div class="L sf">${STAGE.floor}</div></div>
    <div class="zone" style="left:0;top:0;width:${Z.w}px;height:${Z.h}px">${SEG.map(([s, , , nx], i) => `<div class="Z seg">${sceneDOM(s, nx, u + 's' + i, false)}</div>`).join('')}</div>
    <div class="L grain"></div>`;
}
function seek(el, T) {
  const t = cl(T, 0, D - 1e-4);
  let i = SEG.findIndex(([, a, b]) => t >= a && t < b); if (i < 0) i = SEG.length - 1;
  const [s, a, b, nx] = SEG[i], d = b - a, lt = t - a;
  // most effects open on their own layout, not on your plain shot, so the first XF seconds dissolve from your plain shot into it
  const xf = AT > 0 && s === EFF && lt < XF ? 1 - eio(lt / XF) : 0, G = qa(el, '.seg');
  G.forEach((g, j) => { g.style.display = j === i || (xf > 0 && j === 0) ? 'block' : 'none'; g.style.opacity = j === 0 && xf > 0 ? xf.toFixed(3) : ''; g.style.zIndex = j === 0 && xf > 0 ? '2' : ''; });
  runScene(s, G[i], lt, d, nx);
  if (xf > 0) runScene(PLAIN, G[0], t, AT, null);
  if (window.LIVE) (xf > 0 ? [G[i], G[0]] : [G[i]]).forEach(g => qa(g, 'img.me').forEach(m => { const v = LIVE(m.dataset.k, t); if (m.getAttribute('src') !== v) m.setAttribute('src', v); }));   // every live view of you gets your frame at t (p = full frame, c = cut-out)
  const fl = mix(s.bg === 'floor' ? 1 : 0, nx && nx.bg === 'floor' ? 1 : s.bg === 'floor' ? 1 : 0, eio(P(lt, d - .45, .45)));
  q(el, '.sf').style.opacity = fl.toFixed(3);
  const n = Math.floor(T * 24) % 9; q(el, '.grain').style.backgroundPosition = `${(n * 73) % 200}px ${(n * 131) % 200}px`;
  return { i, t: lt, name: s.name };
}
window.EX = { SEG: SEG.map(([s, a, b]) => [s.name, a, b]), D, Z, V, ST, build, seek, PG, FX };

// Effect 04 Portal: a ring of blue light opens below his chin, filled with a turning blue swirl. We fly through it into the next effect.
// No second face in the ring while it holds. The next effect fades in only once the dive has opened the ring out.
(() => {
  const PO = V === 'L' ? { c: [Z.w / 2, Z.h * .79], R: 165 } : V === 'A' ? { c: [Z.w * .8, Z.h * .6], R: 140 } : { c: [540, 1440], R: 220 };
  const IN = .84, RW = .16;   // the window is the inner 84% of the ring; the rim is 16% of the radius
  // absolute seconds (the beat is ~1.0s): opens 0.04-0.34, holds open, dive over the last 0.45s (never before 0.57s)
  const TM = d => { const dv = Math.max(.57, d - .45); return { dv, dl: d - dv }; };
  const rad = t => PO.R * ez(P(t, .04, .3));
  FX[4] = {
    name: NAMES[3], row: 3, bg: 'floor', Send: .7 * Z.w / (PO.R * IN),   // the window shows 70% of the next shot's width, so it reads as him, not as a thin card
    // the window radius in this scene's coords: the inner ring, then it opens out to cover the whole zone by the hand-off
    wr(t, d) { const { dv, dl } = TM(d); return mix(rad(t) * (IN + .02), 1.02 * ZD / this.Send, ez(P(t, dv + .05 * dl, .8 * dl))); },
    html() { return `<style>
      .fx4g{position:absolute;border-radius:50%;box-shadow:0 0 70px 14px rgba(0,113,227,.42),0 30px 60px -10px rgba(0,19,47,.35)}
      .fx4r{position:absolute;border-radius:50%;background:conic-gradient(from 0deg,#0071E3,#5AB0FF,#fff,#5AB0FF,#0071E3,#3B8CFF,#e8f3ff,#3B8CFF,#0071E3);
        -webkit-mask:radial-gradient(closest-side,transparent ${(100 * (1 - RW)).toFixed(1)}%,#000 ${(100 * (1 - RW) + .8).toFixed(1)}%);mask:radial-gradient(closest-side,transparent ${(100 * (1 - RW)).toFixed(1)}%,#000 ${(100 * (1 - RW) + .8).toFixed(1)}%)}
      .fx4f{position:absolute;border-radius:50%;background:radial-gradient(closest-side,#fff 0%,#dcecff 34%,rgba(0,113,227,.55) 78%,#0071E3 100%)}
      .fx4f::after{content:'';position:absolute;inset:0;border-radius:50%;background:repeating-conic-gradient(from 0deg,rgba(255,255,255,.55) 0deg 14deg,rgba(255,255,255,0) 14deg 45deg);-webkit-mask:radial-gradient(closest-side,transparent 18%,#000 70%);mask:radial-gradient(closest-side,transparent 18%,#000 70%)}
      .f[data-s=white] .fx4g{box-shadow:0 0 60px 10px rgba(0,113,227,.30),0 30px 60px -12px rgba(0,19,47,.28)}
      </style>${himView(PT(4), 'me')}<div class="fx4g"></div><div class="fx4f"></div>${SLOT}<div class="fx4r"></div>`; },
    camera(t, d) { const { dv, dl } = TM(d), e = ez(P(t, dv, dl)); return e > 0 ? { a: PO.c, f: [mix(PO.c[0], ZC[0], e), mix(PO.c[1], ZC[1], e)], S: Math.pow(this.Send, e) } : null; },
    seek(cam, t, d) { const r = Math.max(rad(t), this.wr(t, d) / (IN + .02)), { dv, dl } = TM(d), fade = 1 - P(t, dv + .5 * dl, .3 * dl);
      const box = el => Object.assign(el.style, { left: (PO.c[0] - r).toFixed(1) + 'px', top: (PO.c[1] - r).toFixed(1) + 'px', width: (2 * r).toFixed(1) + 'px', height: (2 * r).toFixed(1) + 'px', display: r > .5 ? 'block' : 'none' });
      const g = one(cam, '.fx4g'), rim = one(cam, '.fx4r'), fl = one(cam, '.fx4f'); box(g); box(rim); box(fl);
      fl.style.transform = `rotate(${(-160 * t).toFixed(1)}deg)`; fl.style.opacity = fade.toFixed(3);
      rim.style.transform = `rotate(${(400 * t).toFixed(1)}deg)`; rim.style.opacity = fade.toFixed(3); g.style.opacity = fade.toFixed(3); },
    win(t, d) { return { c: PO.c, r: this.wr(t, d) }; },
    winIn: (t, d) => { const { dv, dl } = TM(d); return P(t, dv + .3 * dl, .25 * dl); },   // late: the ring is already wide when the next shot shows
  };
})();

// Effect 01. Shared helpers for every fx file (cutView) live here too.
// Scene contract (zone coordinates, t = seconds from the scene's start, d = its length, K = d/2 so timings stretch with the beat):
//   { name, row, bg:'blue'|'floor', html(id, inner) with SLOT where the next scene shows, camera(t,d)->{a,f,S}|null,
