// ---------------- 1 Grid Dive: his talking head is one tile. Pull back to a wall of tiles on the stage, dive into the next tile.
const G = (() => { const TW = .2 * Z.w, TH = TW * Z.h / Z.w, g = .035 * Z.w; const at = (i, j) => [ZC[0] + i * (TW + g), ZC[1] + j * (TH + g)];
