    const th = one(cam, '.gt.th'); th.style.boxShadow = `0 ${(24 * foc).toFixed(1)}px ${(50 * foc).toFixed(1)}px rgba(0,19,47,${(.45 * foc).toFixed(3)})`; },
  win(t, d) { const { e1, e2 } = GT(t, d); return { c: G.Th, w: G.TW, h: G.TH, rr: (V !== 'B' ? 10 : 16) * e1 * (1 - e2) }; },
