    camera(t, d) { if (SE === 1) return null; const e = eio(P(t, TO, d - .03 - TO)); return e > 0 ? { a: F, f: [mix(F[0], ZC[0], e), mix(F[1], ZC[1], e)], S: Math.pow(SE, e) } : null; },
    seek(cam, t, d) {
